// model/settings.mjs -- caches, settings clamps and our own settings write applied locally. One part of Model.mjs (D-REL-5); its import and export lines are generated by split-model.mjs on the dev branch.
import {
  SEP, SETTING_RANGES
} from "./build.mjs"
import {
  str, asList, keyedMap, hasOwnKey
} from "./text.mjs"
import {
  channelOrderOf
} from "./channels.mjs"
import {
  optInSetting
} from "./logos.mjs"
import {
  pipOptions
} from "./pip.mjs"
import {
  redactUrls, scrubUrls
} from "./privacy.mjs"
import {
  MAX_SOURCES, MAX_SOURCE_URL, sanitizeInput, sanitizeUrlInput,
  validateSourceUrl, sourceKey
} from "./sources.mjs"
import {
  activeKeyText
} from "./source-records.mjs"

// ------------------------------------------------------------ caches

function parseJsonObject(text) {
  // D-PERF-3 (R30g). This trimmed the WHOLE file -- channels.json at up to
  // 64 MiB, epg-now.json, every helper reply -- with `/^\s+|\s+$/g`, which is
  // quadratic in a whitespace run, and the helper keeps interior runs in
  // names, groups, tvg-ids and stream URLs. JSON.parse would accept the JSON
  // whitespace around a document by itself (space, tab, CR, LF), but NOT a
  // byte-order mark or a no-break space, which this trim has always let a
  // hand-edited state.json carry; so the trim stays, as the engine's own,
  // linear in the length of the text.
  var raw = str(text).trim()
  if (raw === "") return null
  try {
    var parsed = JSON.parse(raw)
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : null
  } catch (e) {
    return null
  }
}

// channels.json -> { ok, channels, meta, error }
function parseChannels(text) {
  var doc = parseJsonObject(text)
  if (!doc) return { ok: false, channels: [], meta: {}, error: "channels cache is empty or not JSON" }
  if (!Array.isArray(doc.channels)) return { ok: false, channels: [], meta: {}, error: "channels cache has no channels array" }
  // D-SG-3: the file's own top-level keys, so null-prototype.
  var meta = keyedMap()
  for (var key in doc) if (key !== "channels" && hasOwnKey(doc, key)) meta[key] = doc[key]
  return { ok: true, channels: doc.channels, meta: meta, error: "" }
}

// D-PERF-4. The service's prepared-channels LRU (Service.applyChannels): a
// parsed, prepared channels.json per entry, so a switch back to a source
// the shell has just shown costs no parse (ARCHITECTURE-SOURCES 4.5). It was
// keyed by the file's TEXT alone, and every helper run writes a new
// `generatedAt`, so a refresh of the source on screen never hit: the new list
// went in front and the old one stayed behind it, unreachable -- one source
// in use, two prepared copies of it held for the session, until a switch to
// a second source displaced the stale one. An entry now carries the SOURCE
// it was read from (the cache directory), a hit needs the same source and
// the same text, and a new entry REPLACES its own source's slot.
function preparedLruFind(lru, text, source) {
  var list = asList(lru)
  var src = str(source)
  for (var i = 0; i < list.length; i++) {
    var e = list[i]
    if (e && e.text === text && str(e.source) === src) return e
  }
  return null
}

// The LRU after `prepared` lands: it first, then the other SOURCES' entries
// in their order, at most `size` in all. Never two entries for one source.
function preparedLruNext(lru, prepared, size) {
  var list = asList(lru)
  var max = Math.max(1, Math.floor(Number(size)) || 1)
  var src = str(prepared && prepared.source)
  var next = [prepared]
  for (var i = 0; i < list.length && next.length < max; i++) {
    var e = list[i]
    if (!e || e === prepared || str(e.source) === src) continue
    next.push(e)
  }
  return next
}

// epg-now.json -> { channels: {tvgId: {now, next}}, meta }
//
// `now` and `next` are programme records: `title`, `start` and `stop`
// always, plus the optional description / category / episode fields M4-02
// widened them with (see EPG_DETAIL_FIELDS). This function deliberately
// does NOT walk them: it hands `doc.channels` over by reference, so a
// widened record costs it nothing beyond the JSON.parse the file already
// paid for, and only programmeDetail -- one row at a time -- reads the new
// fields. `version` is ignored on purpose, as it always has been: an
// unknown version still parses, and a missing field reads as absent rather
// than as a failure.
function parseEpgNow(text) {
  var doc = parseJsonObject(text)
  if (!doc || !doc.channels || typeof doc.channels !== "object" || Array.isArray(doc.channels)) return { ok: false, channels: {}, meta: {} }
  var meta = keyedMap()
  for (var key in doc) if (key !== "channels" && hasOwnKey(doc, key)) meta[key] = doc[key]
  // `channels` stays the parsed object, by reference (above): it is keyed by
  // the provider's tvg-ids and is an ORDINARY object, so every read of it
  // goes through Model.epgMapEntry (the store reader epgEntry reads a
  // legacy store through it too), never `map[tvgId]` (D-SG-3).
  return { ok: true, channels: doc.channels, meta: meta }
}

// epg-now.json -> the guide-data STORE the shell holds (D-EPG-11, R31a).
//
//   { kind: "epg-store", ok, meta, index, text, count, legacy, map }
//
// `kind` is the TAG that says "this is a store": the two functions that read
// one (epgCoverage, epgEntry) still accept the plain map the old whole parse
// gave, and they tell the two apart by this tag, never by the presence of a
// key such as `index` or `map` -- on a plain map every key is a provider's
// tvg-id, so a provider id spelt `index` would otherwise flip the reader
// into store mode and grade that entry's `now`/`next` as the index
// (R30f's shape one layer up, the correctness lens's finding on the first
// cut). A map's values are entry objects, so no provider text can make
// `kind === "epg-store"` true. `count` is the number of DISTINCT ids in the
// index on both paths: the helper cannot write an id twice (it iterates a
// dict), but a hand-built file can, and the index keeps the last line as
// JSON.parse keeps the last key.
//
// The shell used to JSON.parse the whole file and keep `doc.channels` by
// reference: measured at 6.85-7.03 KiB of resident memory a channel for 529
// bytes of JSON, about 67 MiB at 10,000 channels and about 340 MiB at
// MAX_CHANNELS (UNVERIFIED at that size), rebuilt on every 5-minute
// recompute. The store instead keeps ONE text -- the file the FileView
// already holds -- and a null-prototype `index` from tvg-id to
// [offset, length] into it, and parses ONE entry when a row asks
// (epgEntry). Nothing here parses the document whole.
//
// THE SHAPE INDEXED (R31b, written by the helper's write_epg_now): the
// header line, ending in `,"channels":{`; then one channel fragment per
// line, `"<json id>":{...}` with a trailing comma on every line but the
// last; then `}}`. The whole is the same valid JSON document it always was,
// so every other reader (json.load, jq, the old parseEpgNow) is unchanged.
// A line's key is the JSON string literal up to the unescaped closing quote
// -- an id may hold quotes, backslashes, non-ASCII and `__proto__`, and is
// at most 256 code points -- decoded with JSON.parse of that literal; the
// entry slice runs from after `":` to the end of the line minus the
// trailing comma and a CR. The text is kept as it came: offsets are into
// it, trailing newline or none, CRLF or LF.
//
// A LEGACY file (one line, 0.14.3's helper during an update window,
// D-REL-9) or any text the line walk cannot index is accepted ONCE through
// the old whole-parse path and marked `legacy: true`: `map` holds the parsed
// channels, `index` holds the ids whose entry carries a titled programme
// (the old coverage rule), and the next `epg --now-only` recompute (5 min)
// rewrites the file in the new shape. The shape alone triggers no fetch.
//
// R31f (D-SG-3): the index is a null-prototype object, so `__proto__`,
// `constructor` and `hasOwnProperty` are plain tvg-ids on it, and nothing
// here keys a plain object by provider text. R31g: the index holds ids and
// numbers only; an entry's text leaves through epgFields / programmeDetail
// -> sinkText exactly as before.
var EPG_CHANNELS_OPEN = ',"channels":{'
var EPG_STORE_KIND = "epg-store"

function emptyEpgStore() {
  return { kind: EPG_STORE_KIND, ok: false, meta: {}, index: Object.create(null), text: "", count: 0, legacy: false, map: null }
}

function parseEpgNowStore(text) {
  var raw = str(text)
  var store = emptyEpgStore()
  if (raw === "") return store
  var nl = raw.indexOf("\n")
  var header = nl === -1 ? raw : raw.slice(0, nl)
  if (header.charCodeAt(header.length - 1) === 13) header = header.slice(0, -1)
  var indexed = nl !== -1 && header.length > EPG_CHANNELS_OPEN.length
    && header.slice(header.length - EPG_CHANNELS_OPEN.length) === EPG_CHANNELS_OPEN
    ? epgNowIndex(raw, header, nl + 1) : null
  if (indexed) return indexed
  // The old path, once: a single-line file, or a shape the walk refused.
  var doc = parseEpgNow(raw)
  if (!doc.ok) return store
  store.ok = true
  store.meta = doc.meta
  store.map = doc.channels
  store.legacy = true
  for (var id in doc.channels) {
    if (!Object.prototype.hasOwnProperty.call(doc.channels, id)) continue
    var entry = doc.channels[id]
    if (!entry || typeof entry !== "object") continue
    if ((entry.now && str(entry.now.title) !== "") || (entry.next && str(entry.next.title) !== "")) {
      store.index[id] = null
      store.count++
    }
  }
  return store
}

// The line walk. -> a store, or null when a line is not a fragment (the
// caller then takes the old path, so a file this cannot index is never
// blank, only costly, exactly as today). `from` is the offset of the first
// fragment line; `header` is the first line without its CR.
//
// It walks the text by OFFSET and never slices a line out of it: a slice
// per channel is a second UTF-16 copy of the file left for the collector,
// and it was measured in the held RSS (about 1.3 KiB a channel of the
// store's first cut, which read 3.7-4.0 KiB a channel against the text's
// 1.9). The only strings made here are each key's literal and its decoded
// id, which the index keeps.
function epgNowIndex(raw, header, from) {
  var meta = parseJsonObject(header.slice(0, header.length - EPG_CHANNELS_OPEN.length) + "}")
  if (!meta) return null
  var index = Object.create(null)
  var count = 0
  var pos = from
  var length = raw.length
  var closed = false
  while (pos < length) {
    var end = raw.indexOf("\n", pos)
    if (end === -1) end = length
    var stop = end
    if (stop > pos && raw.charCodeAt(stop - 1) === 13) stop--
    if (stop === pos) { pos = end + 1; continue }
    // `}}` on its own line closes the map; anything after it is not a shape
    // this knows.
    if (stop - pos === 2 && raw.charCodeAt(pos) === 125 && raw.charCodeAt(pos + 1) === 125) { closed = true; pos = end + 1; continue }
    if (closed || raw.charCodeAt(pos) !== 34) return null
    // The key: to the first quote not escaped by an odd run of backslashes,
    // within this line.
    var q = pos + 1
    for (;;) {
      q = raw.indexOf('"', q)
      if (q === -1 || q >= stop) return null
      var slashes = 0
      for (var b = q - 1; b > pos && raw.charCodeAt(b) === 92; b--) slashes++
      if (slashes % 2 === 0) break
      q++
    }
    if (raw.charCodeAt(q + 1) !== 58) return null
    var id
    try { id = JSON.parse(raw.slice(pos, q + 1)) } catch (e) { return null }
    if (typeof id !== "string") return null
    var entryEnd = stop
    if (raw.charCodeAt(entryEnd - 1) === 44) entryEnd--
    if (entryEnd <= q + 2) return null
    if (!(id in index)) count++
    index[id] = [q + 2, entryEnd - (q + 2)]
    pos = end + 1
  }
  if (!closed) return null
  return { kind: EPG_STORE_KIND, ok: true, meta: meta, index: index, text: raw, count: count, legacy: false, map: null }
}

// Helper status JSON -> normalized object the UI can render directly.
// Tolerates unknown keys; a bare string error is upgraded to the object
// form; numeric counters (`channelCount`, `groupCount`, `matched`) are
// coerced so bindings never see strings.
function parseHelperStatus(text, kind) {
  var doc = parseJsonObject(text)
  if (!doc) return { ok: false, kind: kind || "", stale: false, error: { code: "no_output", message: "helper produced no JSON" } }
  if (doc.error && typeof doc.error === "string") doc.error = { code: "error", message: doc.error }
  if (doc.error && typeof doc.error === "object") {
    doc.error = { code: str(doc.error.code) || "error", message: str(doc.error.message) || "helper reported failure" }
  }
  if (doc.ok !== true && !doc.error) doc.error = { code: "error", message: "helper reported failure" }
  if (doc.ok === true) doc.error = null
  if (!doc.kind) doc.kind = kind || ""
  doc.stale = doc.stale === true
  var counters = ["channelCount", "groupCount", "matched", "programmeCount", "fetchedAt", "durationMs"]
  for (var i = 0; i < counters.length; i++) {
    if (doc[counters[i]] !== undefined && doc[counters[i]] !== null) {
      var n = Number(doc[counters[i]])
      doc[counters[i]] = isFinite(n) ? n : 0
    }
  }
  if (doc.warnings !== undefined) doc.warnings = asList(doc.warnings)
  return doc
}

var HTTP_REASONS = { 401: "Unauthorized", 403: "Forbidden", 404: "Not Found", 429: "Too Many Requests" }

// D-REL-7 (the split's reviews, P3a). The helper's stub reads and checks all
// of its parts before any of them runs, and refuses with ONE reply, code
// `helper_damaged`, when one is missing, not a regular file, empty, not the
// part the stub's list names (cut off, altered, or from another release, as
// mid-update), not text or not compiling, or when bin/helper/ holds a file
// it does not name (a name starting with "." excepted):
// `{"ok": false, "part": "05-ipc-logos.py", "error": {...}}`. The only cure is
// a fresh copy of the plugin, so that is what the sentence says. It names the
// part and nothing else: `part` is shown only when it has a part's shape, so
// a stray file's name -- anything at all -- never reaches a toast. The
// reply's `error.message` does name the part under bin/helper/ (a path
// relative to the plugin, nothing of the user's), and this sentence never
// reads it.
// Pinned against the stub's real replies by one shared fixture (dev branch).
var HELPER_PART_RE = /^[0-9]{2}-[a-z][a-z0-9-]{0,40}\.py$/

function helperDamagedReason(status) {
  var part = status && typeof status === "object" ? str(status.part) : ""
  return "Plugin files damaged" + (HELPER_PART_RE.test(part) ? " (" + part + ")" : "")
    + SEP + "reinstall the plugin"
}

// Short, credential-free reason per UX 6.3. Maps helper error codes first,
// then falls back to a scrubbed message.
function statusReason(status) {
  if (!status || status.ok === true || !status.error) return ""
  var code = str(status.error.code)
  var message = str(status.error.message)
  if (code === "helper_damaged") return helperDamagedReason(status)
  var http = code.match(/^http_(\d{3})$/)
  if (http) {
    var n = Number(http[1])
    return "HTTP " + n + (HTTP_REASONS[n] ? " " + HTTP_REASONS[n] : "")
  }
  if (code === "network") {
    if (/timed? ?out/i.test(message)) return "Timed out"
    if (/resolve|name or service|nodename|getaddrinfo|no address/i.test(message)) return "Could not resolve host"
    if (/refused/i.test(message)) return "Connection refused"
    if (/certificate|ssl|tls/i.test(message)) return "TLS error"
    return "Network error"
  }
  var table = {
    not_found: "File not found",
    unsafe_path: "Path not allowed",
    unsupported_scheme: "Unsupported URL",
    timeout: "Timed out",
    helper_timeout: "Helper timed out",
    unsafe_redirect: "Unsafe redirect",
    too_large: "Source too large",
    bad_gzip: "Bad gzip data",
    empty_playlist: "Playlist has no channels",
    not_a_playlist: "Not an M3U playlist",
    not_m3u: "Not an M3U playlist",
    not_xmltv: "Not an XMLTV file",
    no_source: "No playlist configured",
    not_implemented: "Helper command not implemented",
    no_output: "Helper produced no output",
    // D-SRC-69 (2026-10-27). `internal` is the helper's catch-all for a BUG
    // (main() in the helper's CLI part): its message is an exception's type
    // and text -- `FileNotFoundError: [Errno 2] No such file or directory:
    // '<runtime path>/...'` reached the Sources result line when the
    // start-up prune removed an add's folder mid-write. Redacted, but an
    // exception is not a sentence, and every surface that shows a helper's
    // reason comes through this function (the playlist and guide-data
    // banners and notifications, the probe's result line, a play failure,
    // the rewind line), so it is mapped once, here. The traceback stays in
    // the journal (the service logs the helper's stderr, redacted).
    internal: "Helper failed unexpectedly",
    // D-SRC-69: a fetch that could not write its cache files (the folder
    // removed or unwritable, the disk full), named by the helper instead of
    // leaving the OSError to main()'s catch-all.
    cache_unwritable: "Could not write the cache",
    // D-SRC-73 (2026-10-27). R25c's refusal (D-SRC-32): a folder the helper
    // writes into -- a source's cache folder, the logo folder, the player's
    // runtime folder -- is a symbolic link whose target is missing or is not
    // a folder, or something that is not a folder sits at its path. The
    // helper's message is R25c's sentence and names the FULL path, which the
    // journal keeps (the service logs the helper's stderr, redacted); what the
    // user reads names none. Until now this code had no entry, so the
    // guide-data banner showed the cache folder's path.
    folder_unusable: "A folder the plugin uses is a broken link or not a folder",
    // D-PLY-30 (2026-10-27): `player start|restart|stop` could not make the
    // player's runtime folder (a parent it cannot write, a full or read-only
    // filesystem) or open the lock file in it (a folder at its name). The
    // helper's message says which, with the error's words and no path; it
    // used to be main()'s `internal` with the exception and the path. A play
    // that fails this way is told in the "did not play" notification.
    runtime_unwritable: "Could not write the player's runtime folder",
    not_running: "mpv is not running",
    unknown_channel: "Unknown channel",
    ipc_error: "mpv did not answer",
    // D-SINK-16: apply_channel refused to load rather than hand a credentialed
    // URL to a player it could not make verify the stream's certificate.
    tls_unverified: "The player would not verify the stream",
    // Source validation and cache verbs (ARCHITECTURE-SOURCES 2.3, 3.1, 4.3)
    empty: "No playlist configured",
    too_long: "URL too long",
    bad_url: "Invalid URL",
    invalid: "Invalid URL",
    scheme: "Unsupported URL",
    relative_path: "Relative path not allowed",
    bad_key: "Invalid cache key",
    duplicate: "Source already listed",
    too_many: "Too many sources",
    busy: "Another fetch is running",
    unknown_source: "Unknown source",
    not_ready: "Sources not loaded yet",
    persist_failed: "Could not save settings",
    // D-SINK-18. The ONE code the shield surfaces. The verb's finer verdicts
    // (absent, symlink, foreign, not_regular, replaced, error) stay inside
    // the helper and the console: configShieldState collapses all of them to
    // "not private", and a user-facing sentence per filesystem accident
    // would be vocabulary nothing acts on.
    config_unsafe: "Settings file is not private",
    cancelled: "Cancelled"
  }
  if (table[code]) return table[code]
  return scrubUrls(message) || "Unknown error"
}

// D-SRC-52 (2026-10-24). `lastError` after a playlist status is applied. A
// failed status writes its reason into `lastError` (applyPlaylistStatus); a
// good one used to leave it there, so the IPC `status` reply carried the
// damaged-files sentence of an update's window after the next good load,
// until a play, a source move or a reset cleared it. Cleared at the sink
// that set it, and ONLY what it set: a sentence another writer put there (a
// play failure's, say) is not this function's to clear, which is why it
// takes the reason the previous status composed rather than a flag.
//   lastError        the property as it stands
//   previousReason   Model.statusReason of the status being replaced,
//                    captured BEFORE the reassignment (the binding moves
//                    with it)
//   nextStatus       the status being applied
function lastErrorAfterStatus(lastError, previousReason, nextStatus) {
  var held = str(lastError)
  if (!nextStatus || nextStatus.ok !== true) return statusReason(nextStatus)
  if (held !== "" && held === str(previousReason)) return ""
  return held
}

function statusHost(status) {
  return status && status.sourceHost ? str(status.sourceHost) : ""
}

// The code of a failed status, "" for a good one or none (D-SRC-71): what
// decides whether a failure line names the provider's host
// (Model.failureFromHost).
function statusCode(status) {
  return status && status.ok !== true && status.error ? str(status.error.code) : ""
}

function statusHealthy(status) {
  return !!(status && status.ok === true && status.running !== false)
}

// Warnings of a successful helper run (D-LIVE-18): strings only, every URL
// reduced to its host (R12), empty for a failed run so the caller keeps the
// warnings of the load whose cache is still in use.
function statusWarnings(status) {
  if (!status || status.ok !== true) return []
  var list = asList(status.warnings)
  var out = []
  for (var i = 0; i < list.length; i++) {
    var text = redactUrls(str(list[i])).trim()
    if (text !== "") out.push(text)
  }
  return out
}

// Wording per helper kind; both warning paths share one shape so they can
// never drift apart (UX 6.3 calls the EPG "Guide data", as the banner does).
// `player` is PO-10's: it does not come from a helper run at all, it comes
// from a setting that is in force right now.
var WARNING_PREFIX = { playlist: "Playlist warning: ", epg: "Guide data warning: ", player: "Player warning: " }

// Which kind a warning already declares, "" when it declares none. The
// footer holds ONE line for the whole service and the guide passes it two
// lists, so a third source (the player's own options) would otherwise need a
// third parameter in Guide.qml. Instead an entry may carry its own prefix
// and is then shown as it stands - `labelWarnings` is the only thing that
// puts one on, so a helper's text can never accidentally look labelled
// unless a helper starts emitting our own footer wording verbatim.
function warningLabel(text) {
  var body = str(text)
  for (var kind in WARNING_PREFIX) {
    if (body.indexOf(WARNING_PREFIX[kind]) === 0) return kind
  }
  return ""
}

function labelWarning(text, kind) {
  var body = str(text)
  if (body === "" || warningLabel(body) !== "") return body
  return (WARNING_PREFIX[str(kind)] || WARNING_PREFIX.playlist) + body
}

// Stamp a whole list with its kind so it can travel in another kind's list.
function labelWarnings(warnings, kind) {
  var list = statusWarnings({ ok: true, warnings: warnings })
  var out = []
  for (var i = 0; i < list.length; i++) out.push(labelWarning(list[i], kind))
  return out
}

// Footer line for the warnings of one helper (UX 6 tone, D-LIVE-18): the
// first warning and, when there are several, how many more; "" without
// warnings. `kind` is "playlist" (default), "epg" or "player", and is only
// consulted for an entry that does not already name its own kind.
function warningLine(warnings, kind) {
  var list = statusWarnings({ ok: true, warnings: warnings })
  if (list.length === 0) return ""
  return labelWarning(list[0], kind) + (list.length > 1 ? " (+" + (list.length - 1) + " more)" : "")
}

// The one warning line the footer's status slot can hold. The playlist's
// warnings describe the channel list itself and win; the EPG's follow with
// their own wording. Each is cleared by the next clean load of its own
// helper, so an EPG warning can outlive a playlist refresh and vice versa.
function footerWarning(playlistWarnings, epgWarnings) {
  var line = warningLine(playlistWarnings, "playlist")
  if (line !== "") return line
  return warningLine(epgWarnings, "epg")
}

// ------------------------------------------------------------ settings

// Our inline settings live on the bar layout entry (shell.json bar.layout.*).
// Returns the entry object or {} so callers can read keys with fallbacks.
function findBarEntry(barConfig, pluginId) {
  var id = str(pluginId)
  if (!barConfig || typeof barConfig !== "object" || !barConfig.layout || typeof barConfig.layout !== "object") return {}
  var sections = ["left", "center", "right"]
  for (var s = 0; s < sections.length; s++) {
    var entries = barConfig.layout[sections[s]]
    if (!Array.isArray(entries)) continue
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i]
      if (typeof entry === "string" && entry === id) return { id: id }
      if (entry && typeof entry === "object" && str(entry.id) === id) return entry
    }
  }
  return {}
}

function settingOf(entry, key, fallback) {
  var value = entry && typeof entry === "object" ? entry[key] : undefined
  return value === undefined || value === null ? fallback : value
}

// How a boolean setting is READ (R2), in one place. The host can hand back a
// real boolean, or the string "false" from a hand-edited shell.json, or a
// value that is simply absent -- and the rule has always been "anything but
// false and the string false means on".
//
// It was written out four times: twice here (showChannelName,
// barShowChannelNumber) and twice in BarWidget.qml, which reads its own
// injected entry rather than going through settingsFrom. The four agreed;
// nothing held them there, and M2-03 added the fourth by copying the third.
function boolSetting(value) {
  return value !== false && str(value) !== "false"
}

function clampInt(value, fallback, min, max) {
  var n = parseInt(String(value), 10)
  if (!isFinite(n)) n = fallback
  if (n < min) n = min
  if (n > max) n = max
  return n
}

function clampSetting(key, value) {
  var range = SETTING_RANGES[key]
  if (!range) return value
  return clampInt(value, range.def, range.min, range.max)
}

// Every setting the plugin knows, clamped (R2). Unknown keys are ignored.
function settingsFrom(entry) {
  // M2-05 section 6: the three PiP keys are read in ONE place
  // (Model.pipOptions), which the service and the guide also call directly,
  // so a clamp can never be written twice and drift (R2, engineering rule 12 (dev branch)).
  var pip = pipOptions(entry)
  return {
    // D-SINK-19. These two are read for ONE purpose since round 11 (R21): the
    // migration of an install written before the change, which named its
    // active source by the URL here. Once the migration marker has landed in
    // state.json a value found here is refused, reported once and stripped
    // (Model.reconcileAction); nothing derives the active source from them,
    // and `sourceKey` below is the mirror of what does.
    playlistUrl: entryInputText(settingOf(entry, "playlistUrl", "")),
    epgUrl: entryInputText(settingOf(entry, "epgUrl", "")),
    // The active source's key, mirrored into the host entry so an install
    // that loses state.json's active key can still find its way back to a
    // source it still has (adoptActiveSource step 2). Read through
    // activeKeyText so a hand-edited value cannot become a path component.
    // NOT the authority: state.json is (activeKeyOf).
    sourceKey: activeKeyText(settingOf(entry, "sourceKey", "")),
    refreshMinutes: clampSetting("refreshMinutes", settingOf(entry, "refreshMinutes", SETTING_RANGES.refreshMinutes.def)),
    mpvArgs: str(settingOf(entry, "mpvArgs", "")),
    showChannelName: boolSetting(settingOf(entry, "showChannelName", true)),
    maxRecents: clampSetting("maxRecents", settingOf(entry, "maxRecents", SETTING_RANGES.maxRecents.def)),
    barLabelMaxWidth: clampSetting("barLabelMaxWidth", settingOf(entry, "barLabelMaxWidth", SETTING_RANGES.barLabelMaxWidth.def)),
    // ---- channel numbers (M2-03 7.1)
    channelOrder: channelOrderOf(settingOf(entry, "channelOrder", "playlist")),
    numberEntryMs: clampSetting("numberEntryMs", settingOf(entry, "numberEntryMs", SETTING_RANGES.numberEntryMs.def)),
    barShowChannelNumber: boolSetting(settingOf(entry, "barShowChannelNumber", true)),
    // ---- logos (M2-04). optInSetting, not boolSetting: see the comment there.
    showLogos: optInSetting(settingOf(entry, "showLogos", false)),
    // ---- picture in picture (M2-05 section 6)
    pipCorner: pip.corner,
    pipSizePercent: pip.sizePercent,
    pipMargin: pip.margin
  }
}

// D-SINK-19 round 8, R18a. THE ONE NORMALISER for a value read from the bar
// entry's two input keys (`playlistUrl`, `epgUrl`).
//
// Round 7's P1: Model.retiredInputsToKeep compared the PUBLISHED entry's
// value raw against the service's snapshot, and the snapshot comes from
// settingsFrom, which trims. `omarchy bar set` does not trim (the host's
// omarchy-bar hands the value to `jq --arg` as typed), so a value with
// surrounding whitespace was never "consumed": a refused credential stayed in
// shell.json, a removed source came back at the next start, and on the
// echoing host a pending EPG beside it looped. With the one-line trim the
// node suite read the same count as without it -- nothing could see it.
//
// So there is ONE form, and every comparison of an entry value -- against a
// snapshot, a record, or another entry value -- goes through it:
//   entryInputText  settingsFrom's own trim (every \s at either edge). The
//                   service's snapshots are taken from `settings`, which is
//                   this; a raw published value becomes this before anything
//                   compares it.
//   entryInputForm  then what adoption does with it: sanitizeUrlInput (the
//                   leading BOM, the ASCII-whitespace / NBSP edges, the cap;
//                   nothing inside deleted, D-SRC-63), then
//                   validateSourceUrl as a CLI value of that kind. `form` is
//                   the validated URL when it passes (what a record stores
//                   and what findSourceByUrl compares) and the sanitized text
//                   when it does not (a refused value is still one value,
//                   whatever spacing it came with). `text` "" means NO input:
//                   a value of whitespace or control characters alone is the
//                   same as an absent key on every path, which it was not --
//                   an EPG of "\u0007" validated as the EMPTY guide URL and
//                   adoptActiveSource replaced the active record's guide URL
//                   with "" (found by this ruling's search, R4 says an empty
//                   EPG input is a no-op).
// Two forms are the same input exactly when their `form`s are equal
// (sameEntryInput). Nothing here is a URL the caller did not already hold.
function entryInputText(value) {
  return str(value).trim()
}

function entryInputForm(name, value) {
  // "No input" is still judged by sanitizeInput's emptiness (R4, R18a: a
  // value of whitespace or control characters alone is an absent key), but
  // the value that is validated is the URL boundary's (D-SRC-63): nothing
  // inside it deleted, so `http://u:pa<TAB>ss@h.test/x` set with
  // `omarchy bar set` is refused as invalid rather than adopted as `pass`.
  if (sanitizeInput(entryInputText(value), MAX_SOURCE_URL + 1) === "") return { text: "", ok: false, url: "", form: "" }
  var text = sanitizeUrlInput(entryInputText(value), MAX_SOURCE_URL + 1)
  var v = validateSourceUrl(text, name === "epgUrl" ? { kind: "epg", origin: "cli" } : { origin: "cli" })
  var ok = v.ok === true && str(v.url) !== ""
  return { text: text, ok: ok, url: ok ? str(v.url) : "", form: ok ? str(v.url) : text }
}

function sameEntryInput(name, a, b) {
  return entryInputForm(name, a).form === entryInputForm(name, b).form
}

// ---- our own settings write, applied locally (D-LIVE-20 / D-LIVE-21)
//
// The host publishes `barConfig` to a plugin from a `shellConfig` change
// handler (shell.qml:66 -> pluginsChanged -> syncPluginApis -> publicBarConfig),
// and a QML change handler runs before the bindings that depend on the same
// property are re-evaluated. So `shell.barConfig` reaches a plugin one
// shellConfig write late: an external write is flushed by the next one (the
// FileView re-reads the foreign change), but a plugin's own write is the
// last one there is and never comes back. A plugin must therefore apply its
// own successful write itself and never wait for the echo.
//
// `ownWrite` = { base, value }: `base` is the host settings the write was
// made against, `value` the playlist / EPG URLs written. The override is in
// force only while the host still reports `base`; the moment the host
// reports anything else -- our echo, or somebody else's write -- it lapses
// and the host wins again. That makes the echo idempotent (our own value
// arrives identical to what is already applied, so nothing changes and
// nothing is applied twice) and keeps an external change authoritative.

// Does a plugin's own write still stand in for the host's value?
function ownWriteInForce(hostSettings, ownWrite) {
  if (!ownWrite || typeof ownWrite !== "object") return false
  var base = ownWrite.base
  var value = ownWrite.value
  if (!base || typeof base !== "object" || !value || typeof value !== "object") return false
  var host = hostSettings || {}
  // Over the keys the write actually carries, rather than the two URL keys
  // by name. M2-04 made `showLogos` the third thing the plugin writes about
  // itself, and a rule spelled as two field comparisons would have silently
  // held a logo override in force while the host changed it underneath.
  // Comparison is by `str` so a boolean and the string "false" a hand-edited
  // shell.json can produce are the same value, which is what boolSetting and
  // optInSetting already assume everywhere else.
  for (var key in base) {
    if (!Object.prototype.hasOwnProperty.call(base, key)) continue
    if (str(host[key]) !== str(base[key])) return false
  }
  return true
}

// The settings the plugin acts on: the host's, with our own pending write
// laid over the keys that write carried, while it is still in force. Every
// other key always comes from the host.
function settingsWithOwnWrite(hostSettings, ownWrite) {
  var host = hostSettings || {}
  if (!ownWriteInForce(host, ownWrite)) return host
  var out = {}
  // D-SG-3: own keys only, never `__proto__` (the host's entry is the user's
  // file, parsed by the host).
  for (var k in host) if (k !== "__proto__" && hasOwnKey(host, k)) out[k] = host[k]
  for (var w in ownWrite.value) {
    if (Object.prototype.hasOwnProperty.call(ownWrite.value, w)) out[w] = ownWrite.value[w]
  }
  return out
}

// The record of a write just made against `hostSettings`, over any set of
// keys. `base` is what the host said at the moment of the write, which is how
// the override knows to lapse when the host says anything else.
function ownWriteOf(hostSettings, values) {
  var host = hostSettings || {}
  var base = {}
  var value = {}
  for (var key in values) {
    if (!Object.prototype.hasOwnProperty.call(values, key)) continue
    base[key] = host[key]
    value[key] = values[key]
  }
  return { base: base, value: value }
}

// Every key this plugin owns inside the host's bar entry.
//
// D-LOGO-2, and the reason all of them are always stated. The entry handed to
// `updateEntryInline` is composed from `barConfig`, which the host publishes
// ONE WRITE BEHIND (see the last section of OMARCHY-PLUGIN-CONTRACT.md (dev
// branch)). A write that mentions only its own key therefore carries the
// PREVIOUS value of every other key back to disk -- so turning logos off and
// then editing a source URL wrote `showLogos: true` again, the setting came
// back on by itself, and the fetch resumed. The same hole existed in the
// other direction.
//
// Stating all of them on every write makes both writers idempotent and makes
// neither able to revert the other. It is cheap because there are two.
//
// D-SINK-19 took the URLs OFF this list and put `sourceKey` on it. The list
// is the only thing that decides what a write carries, so that one edit moves
// both writers at once -- which is the D-LOGO-2 lesson spent rather than
// relearned.
var OWNED_SETTINGS = ["sourceKey", "showLogos"]

// Keys this plugin USED to own (D-SINK-19). They are read by the migration
// alone (R21a: until the migration marker has landed in state.json) and the
// plugin never writes one back: from the moment the marker has landed every
// owned write removes them (R21b), heal and patch alike.
//
// Removal lives in `entryWith`, which is the single funnel both
// `updateEntryInline` call sites go through, rather than in either caller: a
// rule written at one of two sites is the shape D-LOGO-2 and rule 15 are
// both about. The consequence is deliberate and is what makes the migration
// cheap -- an owned write heals an old entry.
//
// R16 (round 5) still decides WHICH owned write may name `sourceKey`: the key
// mirror heals once the file agrees with memory (writeActive under R13), and
// the logo toggle writes `showLogos` alone before the first state load or
// while a state write is parked, in flight or failed (`ownedWriteMode`).
// What a write keeps of THESE keys is no longer the caller's question, nor a
// landed-state comparison (R17a's held/consumed rule and R20c's patch rule
// are withdrawn): it is retiredInputsToKeep, over the marker.
var RETIRED_SETTINGS = ["playlistUrl", "epgUrl"]

// D-SINK-19 round 11, R21b. WHAT THIS SESSION HAS ALREADY HANDLED.
//
// Every value the service has migrated or refused off the bar entry, by
// setting, as its one form (entryInputForm). It is an IN-MEMORY snapshot and
// nothing else -- the ruling says so, and the persisted snapshot of round 10
// (R20b's entryInputs) is what it replaces: a value equal to one this session
// already handled is neither adopted nor reported again, so the lagging
// host's stale publish of a value the plugin has just stripped (rule 9)
// re-adopts nothing and re-reports nothing. A restart starts it empty, which
// is right: after the marker has landed the next start refuses whatever the
// entry carries, and reports it once.
//
// It is an ORDERED list, most recent last, and the two phases ask it two
// different questions. After the marker: "has this session seen this value
// at all" (entryInputSeen), so each value is reported once. During the
// migration: "is this the value the entry carried LAST time" (entryInputLast),
// which is R1's snapshot -- a user who sets B and then the migration's own A
// again inside the window (a failing disk keeps it open all session) set A
// last, and membership alone swallowed that A (lane-key-m1's adapted round-10
// matrix, ACT:cli on `cliP_B > cliP_N`). What neither can tell apart is a
// re-set of the value the entry ALREADY carries from the host's stale publish
// of it -- the entry does not change -- which is why it is a no-op.
//
// Bounded, because it is a list a user can grow by typing: past
// MAX_SEEN_INPUTS values of one setting the oldest is dropped, and a value
// that old reports once more if it comes back -- a report too many, never an
// adoption (after the marker nothing is adopted at all).
var MAX_SEEN_INPUTS = 32

function entryInputSeen(seen, name, value) {
  var f = entryInputForm(name, value)
  if (f.text === "") return false
  var list = seen && typeof seen === "object" && Object.prototype.toString.call(seen[name]) === "[object Array]" ? seen[name] : []
  return list.indexOf(f.form) !== -1
}

// Is `value` the most recent value this session saw for `name`?
function entryInputLast(seen, name, value) {
  var f = entryInputForm(name, value)
  if (f.text === "") return false
  var list = seen && typeof seen === "object" && Object.prototype.toString.call(seen[name]) === "[object Array]" ? seen[name] : []
  return list.length > 0 && list[list.length - 1] === f.form
}

// `values` maps setting names to what the entry carries now; every one that
// is an input (a non-empty form) becomes the most recent of its setting --
// appended when new, moved to the end when seen before. A NEW object
// whenever anything moves, the SAME object otherwise, so a QML `property
// var` holding it raises a change signal only when it changed.
function entryInputsSeenAfter(seen, values) {
  var have = seen && typeof seen === "object" ? seen : {}
  var v = values || {}
  var out = null
  for (var i = 0; i < RETIRED_SETTINGS.length; i++) {
    var name = RETIRED_SETTINGS[i]
    var f = entryInputForm(name, v[name])
    if (f.text === "" || entryInputLast(have, name, v[name])) continue
    if (out === null) {
      out = {}
      for (var k in have) if (Object.prototype.hasOwnProperty.call(have, k)) out[k] = asList(have[k]).slice()
    }
    var list = (out[name] || []).filter(function (x) { return x !== f.form })
    list.push(f.form)
    while (list.length > MAX_SEEN_INPUTS) list.shift()
    out[name] = list
  }
  return out === null ? have : out
}

// D-SINK-19 round 11, R21b / R21c. THE ONE REPORT of a value taken off the
// bar entry without being adopted. Names the setting and the Sources screen,
// and NEVER the value: the value can be a credentialed URL (rule 5), and the
// report goes to a desktop notification and the console. `name` is a setting
// name the caller holds as a constant; anything else reads as "A URL
// setting", so no caller can route a value into the text by mistake.
//   retired    the migration has landed: the entry is not read any more
//   no-source  a guide URL at the migration with no source to guide (R21c)
//   invalid    a migration value that does not validate
//   invalid-pair  R29d: a playlistUrl that does not validate AND the epgUrl set
//              beside it, told in ONE notice and removed together (the guide
//              URL is never adopted onto another source); named from the
//              playlist when `name` is playlistUrl, from the guide URL when it
//              is epgUrl (the playlist was told about before)
// -> { title, body }.
function entryInputNotice(name, reason) {
  var setting = RETIRED_SETTINGS.indexOf(str(name)) !== -1 ? str(name) : "A URL setting"
  var where = "the guide's Sources screen"
  var r = str(reason)
  if (r === "no-source") {
    return { title: "Bar setting removed",
             body: setting + " was removed from the bar settings: no source was set up for it to guide. Add the source with its EPG URL in " + where + "." }
  }
  if (r === "invalid-pair") {
    // The two names are composed, never written into the sentence beside a
    // verb, so the shipped-copy test (no literal sends the user to a retired
    // setting) reads the same rule here as everywhere.
    var playlist = RETIRED_SETTINGS[0], guide = RETIRED_SETTINGS[1]
    if (setting === guide) {
      return { title: "Bar setting removed",
               body: guide + " in the bar settings came with a " + playlist + " that was not a usable URL, and was removed with it. Add or edit sources in " + where + "." }
    }
    return { title: "Bar setting removed",
             body: setting + " in the bar settings was not a usable URL and was removed, with the " + guide + " beside it. Add or edit sources in " + where + "." }
  }
  if (r === "invalid") {
    return { title: "Bar setting removed",
             body: setting + " in the bar settings was not a usable URL and was removed. Add or edit sources in " + where + "." }
  }
  // R27d (D-SRC-44): the migration did not run because Sources is full. The
  // URL rests in state.json's parked pair since D-SRC-64 (on the bar entry
  // before it); nothing names it or the entry's label.
  // R28b: and the guide URL set beside it is held with it, so the sentence
  // names both -- they move in together once a source is removed.
  // R29e (2026-10-20, round 2's P3): and it says which source is active
  // after that, because the migration makes the bar's playlist active over
  // whichever source the user had picked meanwhile (Service.retryHeldMigration
  // -> Model.reconcileSources' withActiveKey; pinned through Service.qml).
  if (r === "full") {
    return { title: "Sources is full",
             body: "The playlist set on the bar, and its guide URL if one is set, were not moved into Sources: Sources already holds " + MAX_SOURCES + " sources, the most it can. Remove one in " + where + " and the bar's playlist and its guide move in together; the bar's playlist then becomes the active source." }
  }
  return { title: "Bar setting ignored",
           body: setting + " is no longer read from the bar settings and was removed. Add or switch sources in " + where + "." }
}

// The patch for a settings write: every owned key, at the value it should
// hold AFTER this write. `effective` is what the plugin currently acts on
// (settings, i.e. the host's values with any own-write already laid over
// them), and `overrides` is what this particular write is changing.
function ownedEntryPatch(effective, overrides) {
  var eff = effective || {}
  var ov = overrides || {}
  var out = {}
  for (var i = 0; i < OWNED_SETTINGS.length; i++) {
    var key = OWNED_SETTINGS[i]
    out[key] = Object.prototype.hasOwnProperty.call(ov, key) ? ov[key] : eff[key]
  }
  return out
}

// `ownWriteForKey(hostSettings, key)` USED TO BE HERE. Its only caller was
// Service.applyOwnWrite, which nothing called (dead since b2a4986, found by
// the D-SINK-19 review); the live write is `writeOwnedEntry`, which records
// `ownWriteOf(hostSettings, ownedEntryPatch(settings, overrides))`, and the
// tests now call that composition rather than a helper the shipping path
// never reached (rule 14).

// Can `updateEntryInline` carry our settings at all? It rewrites a layout
// entry in place, so it needs an object entry with our id: a bare-string
// entry (`"io.github.rmcdavid.iptv"`) and an absent entry both make it
// return false without persisting, and that is a real persist failure. A
// false return with a writable entry means "nothing to change" instead,
// which is success (the host already stores what we asked for).
function barEntryWritable(barConfig, pluginId) {
  var id = str(pluginId)
  if (!barConfig || typeof barConfig !== "object" || !barConfig.layout || typeof barConfig.layout !== "object") return false
  var sections = ["left", "center", "right"]
  for (var s = 0; s < sections.length; s++) {
    var entries = barConfig.layout[sections[s]]
    if (!Array.isArray(entries)) continue
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i]
      if (entry && typeof entry === "object" && str(entry.id) === id) return true
    }
  }
  return false
}

// D-SRC-15 (R11). The second half of a "wait-entry" plan (pointerWritePlan):
// the entry mirror that waited for the parked state save is written only
// when that save has LANDED -- the FileView's `saved` signal, not setText
// returning -- and the helper's start-up `state init` exited 0. Loading the
// entry with the key is also the write that takes the URL off it, and the
// URL on the entry is the only copy of a source whose state write failed, so
// on either failure the entry is left exactly as it is ("drop": the next
// start re-adopts it, the idempotent old shape) and the service logs a line
// with no URL in it. "wait" while the save is parked or in flight, "flush"
// once it has landed, "none" with nothing held.
//
// -> { act: "none" | "wait" | "flush" | "drop", reason }. Called from
// stateInitProc's exit (after the parked save is issued), from stateFile's
// `saved` and from its `saveFailed`, and (R13) from persistActive the moment
// it holds a key on the dirsReady route.
//
// R22a (round 12): `blocked`, the no-write mode's reason, drops a held key
// whatever else is true -- no state write will land to wait for, and the
// entry is left exactly as it is.
function entryFlushDisposition(ctx) {
  var c = ctx || {}
  if (c.pendingKey === null || c.pendingKey === undefined) return { act: "none", reason: "nothing-held" }
  if (str(c.blocked) !== "") return { act: "drop", reason: "state-unreadable" }
  if (c.dirsReady !== true) return { act: "wait", reason: "dirs" }
  if (c.initOk !== true) return { act: "drop", reason: "init-failed" }
  // R13: a save still parked or in flight outranks a STALE failure. The flag
  // is sticky until a later write lands, and persistActive settles a fresh
  // hold at once while that write is in the air -- checked the other way
  // round, a switch made after any earlier failure dropped its mirror
  // before its own write had reported (found by the R13 service-order
  // driver). The in-flight write's `saved` clears the flag and flushes;
  // its `saveFailed` keeps the flag and drops.
  if (c.savePending === true || (Number(c.savesInFlight) || 0) > 0) return { act: "wait", reason: "save-in-flight" }
  if (c.saveFailed === true) return { act: "drop", reason: "save-failed" }
  return { act: "flush", reason: "saved" }
}

// D-SINK-19 round 9, R19d (D-SRC-18). THE MIRROR A FAILED SAVE OWES.
//
// A held key mirror whose state save FAILED is dropped (entryFlushDisposition
// "drop", reason save-failed): the entry is left exactly as it is, because an
// input on it may be the only copy of what the failed write carried. But the
// in-memory state goes on, and a LATER save that lands writes all of it --
// the adoption the failed write carried included, and anything the user did
// since, such as an in-app guide URL edit made after the input. Nothing then
// took the old input off the entry, so the next start re-adopted it, seen
// "now", over the later edit (D-SRC-18). The order WAS known, in memory; the
// write that recorded it simply never followed.
//
// So the drop leaves a debt, and the first save to LAND with nothing held,
// parked, in flight or failed pays it: one key mirror, through the funnel,
// which strips what is consumed. -> "rewrite" | "none".
function owedMirrorAction(ctx) {
  var c = ctx || {}
  if (c.owed !== true) return "none"
  if (c.pendingKey !== null && c.pendingKey !== undefined) return "none"
  if (c.savePending === true || (Number(c.savesInFlight) || 0) > 0 || c.saveFailed === true) return "none"
  return "rewrite"
}

// R16 (D-SINK-19 round 5). What an owned-entry write that is NOT the key
// mirror may carry. writeOwnedEntry has two callers, and R13 gated one: the
// logo toggle (Service.setShowLogos) mirrored `sourceKey` from MEMORY with no
// plan and stripped the retired URL keys, so after a failed state write --
// the state R13 leaves on purpose, the URL on the entry being the only copy
// -- one `g` in Sources wrote a key the file did not have and took the URL
// off; the record then existed nowhere durable and the next start lost it
// (round-4 review, measured live and at the Model layer: losses 4 of 4 on
// every D-SINK-19 tree). Rule 15's shape: the second writer.
//
//   heal   nothing of ours is outstanding: the file agrees with memory, so
//          the write may name every owned key at its effective value, as
//          the mirror does
//   patch  the state has not been loaded yet, or a state write is parked,
//          in flight or failed: the write carries `showLogos` alone, with
//          `sourceKey` as the host PUBLISHES it (the patch's sourceKey is
//          the host's own value through `ownedEntryPatch` over `settings`,
//          never memory's). Healing is the key mirror's job, through
//          writeActive under R13, once the file agrees with memory again
// Neither answer decides what happens to `playlistUrl` and `epgUrl` any more:
// that is retiredInputsToKeep, over the migration marker (R21), the same for
// both. Before round 11 the patch carried them as the host published them,
// and on the lagging host that carried back a URL the plugin's own heal had
// just stripped (D-SINK-20); R20c's landed-state narrowing of it is withdrawn
// with the route it served.
//
// R16 as amended (D-SINK-19 round 6, the round-5 data-loss lens's P2): a
// FOURTH input, `stateLoaded`. Before the first state load memory is
// Model.emptyState() and none of the three save flags is raised, so the
